parameters.jsCode:
// ---------- Workflow Input ----------
const input = $('When Executed by Another Workflow')
  .first()
  .json;

// ---------- Project Item ----------
const projectItem = $('get project item')
  .first()
  .json
  .data
  .repository
  .issue
  .projectItems
  .nodes[0];

// ---------- Project Fields ----------
const fields = $('get project fields')
  .first()
  .json
  .data
  .node
  .fields
  .nodes;

// ---------- Feld suchen ----------
const projectField = fields.find(
  f => f.name.toLowerCase() === String(input.field).toLowerCase()
);

if (!projectField) {
  throw new Error(`Project field '${input.field}' not found.`);
}

if (!projectField.options) {
  throw new Error(
    `Project field '${input.field}' is not a Single Select field.`
  );
}

// ---------- Option suchen ----------
const option = projectField.options.find(
  o => o.name.toLowerCase() === String(input.value).toLowerCase()
);

if (!option) {
  throw new Error(
    `Option '${input.value}' not found in field '${input.field}'.`
  );
}

// ---------- Ergebnis ----------
return [{
  json: {
    issue: input.issue,

    projectId: projectItem.project.id,
    itemId: projectItem.id,

    fieldId: projectField.id,
    optionId: option.id,

    field: projectField.name,
    value: option.name
  }
}];
